// Deutsch (Deutschland) UI catalog — partial by design (owner 2026-10-13: periodic translation; normal
// development maintains only zh-CN + en). Missing keys fall back to en at lookup time
// (i18n/index.tsx); `...modulesEn` first keeps every key present, the entries below override.
//
// Glossar (2026-10-15, vollständige Übersetzung; du-Form, kurze UI-Sprache):
//   Profile→Profil · turn→Durchlauf · session→Sitzung · queue→Warteschlange · steer→einsteuern
//   delegation→Delegierung · approval→Freigabe (freigeben) · idle→inaktiv · host→Host
//   runtime→Runtime · release→Release · update→Aktualisierung · roll back→zurückrollen/Rollback
//   workflow→Workflow · run→Lauf (Laufplan, Lauf-ID) · quick launch→Schnellstart
//   side chat→Side-Chat · quota→Kontingent · usage limit→Nutzungslimit · reasoning level→Denkstufe
//   tray→Infobereich · Appearance (settings section)→Aussehen · tab→Tab · gutter→Rand
//   notifications: Ereignis → Stufe, Stufe → Methode · job→Job (Job-Dienst)
//   one-shot agents→einmalige {{agents}} · one-way→unumkehrbar · preflight→Vorabprüfung
//   prefill/Preset bleiben Produktbegriffe (Preset, Eigene) · provider→Anbieter
