  "claude-science.removeConfirm": "Das Konto {name} entfernen? Sein Claude Science stoppt und wird aus cutex ausgetragen. Das Kontoverzeichnis {home} bleibt bestehen und wird nicht gelöscht; füge es mit demselben Verzeichnis wieder hinzu, um weiterzumachen.",
