  "claude-science.form.home": "Kontoverzeichnis (auf dem Host)",
  "claude-science.form.homeHint": "Das HOME des Kontos, wird bei Bedarf angelegt. Ein bestehendes Verzeichnis übernimmt ein Konto, das bereits angemeldet ist (stoppe dieses Konto zuerst, wo immer es sonst läuft). Höchstens 41 Zeichen (ein Claude-Science-Limit). Das Entfernen des Kontos löscht es niemals.",
