  "claude-science.login.step1": "Klicke Öffnen: der Browser der App öffnet das Konto auf der lokalen Anmeldeseite von Claude Science (ein Einmal-Link, bei jedem Öffnen neu erzeugt). Klicke Sign in.",
  "claude-science.login.step2": "Klicke dort auf Sign in on the web und melde dich bei claude.ai mit diesem Konto an. Zeigt claude.ai ein anderes Konto, wechsle oder melde dich zuerst ab; du kannst diesen Schritt auch in einem anderen Browser erledigen, in dem dieses Konto angemeldet ist.",
