  "claude-science.login.why": "Jedes Konto meldet sich einmal in seinem eigenen Verzeichnis an, nicht mit dem Claude-Login eines cutex-Profils: ein gemeinsames würde die Refresh-Tokens gegenseitig verdrängen.",
